From 5a069401c03cabeb3a7c413c7c3aa1fa915f5c56 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 29 Oct 2026 13:22:06 +0100
Subject: [PATCH] shell/scripting: don't crash reading a panel whose screen is
 gone

Reading a panel property such as height from a script crashed
plasmashell when the panel's screen was gone, as the config lookup went
through the missing screen. Now it uses the panel's own config groups.

BUG: 524224
---
 shell/panelview.cpp       |  6 ++---
 shell/panelview.h         |  4 ++--
 shell/scripting/panel.cpp | 46 +++++++++++++--------------------------
 shell/scripting/panel.h   |  1 -
 4 files changed, 20 insertions(+), 37 deletions(-)

diff --git a/shell/panelview.cpp b/shell/panelview.cpp
index 5c0ac43e71..25f0092d4b 100644
--- a/shell/panelview.cpp
+++ b/shell/panelview.cpp
@@ -158,9 +158,9 @@ KConfigGroup PanelView::panelConfig(ShellCorona *corona, Plasma::Containment *co
     }
 }

-KConfigGroup PanelView::panelConfigDefaults(ShellCorona *corona, Plasma::Containment *containment, QScreen *screen)
+KConfigGroup PanelView::panelConfigDefaults(ShellCorona *corona, Plasma::Containment *containment)
 {
-    if (!containment || !screen) {
+    if (!containment) {
         return {};
     }

@@ -197,7 +197,7 @@ KConfigGroup PanelView::resolutionDependentConfig()

 KConfigGroup PanelView::configDefaults() const
 {
-    return panelConfigDefaults(m_corona, containment(), m_screenToFollow);
+    return panelConfigDefaults(m_corona, containment());
 }

 Qt::Alignment PanelView::alignment() const
diff --git a/shell/panelview.h b/shell/panelview.h
index eb276bf7f6..5f56849fe5 100644
--- a/shell/panelview.h
+++ b/shell/panelview.h
@@ -231,9 +231,9 @@ public:

     Q_INVOKABLE void clonePanelTo(Plasma::Types::Location location, QScreen *screen);

-    /* Both Shared with script/panel.cpp */
     static KConfigGroup panelConfig(ShellCorona *corona, Plasma::Containment *containment, QScreen *screen);
-    static KConfigGroup panelConfigDefaults(ShellCorona *corona, Plasma::Containment *containment, QScreen *screen);
+    /* Shared with scripting/panel.cpp */
+    static KConfigGroup panelConfigDefaults(ShellCorona *corona, Plasma::Containment *containment);

     void updateExclusiveZone();

diff --git a/shell/scripting/panel.cpp b/shell/scripting/panel.cpp
index b60a3f4275..129da5ff7d 100644
--- a/shell/scripting/panel.cpp
+++ b/shell/scripting/panel.cpp
@@ -108,27 +108,11 @@ PanelView *Panel::panel() const
     return corona()->panelView(c);
 }

-KConfigGroup Panel::panelConfig() const
-{
-    int screenNum = qMax(screen(), 0); // if we don't have a screen (-1) we'll be put on screen 0
-
-    if (corona()->screenPool()->screenOrder().size() < screenNum) {
-        return {};
-    }
-    auto s = corona()->screenPool()->screenForId(screenNum);
-    return PanelView::panelConfig(corona(), containment(), s);
-}
-
 // NOTE: when we don't have a view we should write only to the defaults group as we don't know yet during startup if we are on the "final" screen resolution yet
+// This group and its parent don't depend on a screen, so they also work for a panel whose screen is gone
 KConfigGroup Panel::panelConfigDefaults() const
 {
-    int screenNum = qMax(screen(), 0); // if we don't have a screen (-1) we'll be put on screen 0
-
-    if (corona()->screenPool()->screenOrder().size() < screenNum) {
-        return {};
-    }
-    auto s = corona()->screenPool()->screenForId(screenNum);
-    return PanelView::panelConfigDefaults(corona(), containment(), s);
+    return PanelView::panelConfigDefaults(corona(), containment());
 }

 QString Panel::alignment() const
@@ -137,7 +121,7 @@ QString Panel::alignment() const
     if (panel()) {
         alignment = panel()->alignment();
     } else {
-        alignment = panelConfig().parent().readEntry("alignment", 0);
+        alignment = panelConfigDefaults().parent().readEntry("alignment", 0);
     }

     switch (alignment) {
@@ -163,11 +147,11 @@ void Panel::setAlignment(const QString &alignment)
     if (panel()) {
         panel()->setAlignment(Qt::Alignment(a));
     } else {
-        panelConfig().parent().writeEntry("alignment", a);
+        panelConfigDefaults().parent().writeEntry("alignment", a);
     }
 }

-// NOTE: lengthMode also reads and writes directly from panelConfig() because it
+// NOTE: lengthMode also reads and writes directly from the parent group because it
 // is resolution independent
 QString Panel::lengthMode() const
 {
@@ -175,7 +159,7 @@ QString Panel::lengthMode() const
     if (panel()) {
         lengthMode = panel()->lengthMode();
     } else {
-        lengthMode = panelConfig().parent().readEntry("panelLengthMode", 0);
+        lengthMode = panelConfigDefaults().parent().readEntry("panelLengthMode", 0);
     }

     switch (lengthMode) {
@@ -202,7 +186,7 @@ void Panel::setLengthMode(const QString &mode)
     if (panel()) {
         panel()->setLengthMode(lengthMode);
     } else {
-        panelConfig().parent().writeEntry("panelLengthMode", (int)lengthMode);
+        panelConfigDefaults().parent().writeEntry("panelLengthMode", (int)lengthMode);
     }
 }

@@ -304,7 +288,7 @@ QString Panel::hiding() const
     if (panel()) {
         visibility = panel()->visibilityMode();
     } else {
-        visibility = panelConfig().parent().readEntry("panelVisibility", 0);
+        visibility = panelConfigDefaults().parent().readEntry("panelVisibility", 0);
     }

     switch (visibility) {
@@ -334,7 +318,7 @@ void Panel::setHiding(const QString &mode)
     if (panel()) {
         panel()->setVisibilityMode(visibilityMode);
     } else {
-        panelConfig().parent().writeEntry("panelVisibility", (int)visibilityMode);
+        panelConfigDefaults().parent().writeEntry("panelVisibility", (int)visibilityMode);
     }
 }

@@ -343,7 +327,7 @@ bool Panel::floating() const
     if (panel()) {
         return panel()->floating();
     } else {
-        return panelConfig().parent().readEntry("floating", true);
+        return panelConfigDefaults().parent().readEntry("floating", true);
     }
 }

@@ -352,7 +336,7 @@ void Panel::setFloating(bool floating)
     if (panel()) {
         panel()->setFloating(floating);
     } else {
-        panelConfig().parent().writeEntry("floating", (int)floating);
+        panelConfigDefaults().parent().writeEntry("floating", (int)floating);
     }
 }

@@ -361,7 +345,7 @@ bool Panel::floatingApplets() const
     if (panel()) {
         return panel()->floatingApplets();
     } else {
-        return panelConfig().parent().readEntry("floatingApplets", false);
+        return panelConfigDefaults().parent().readEntry("floatingApplets", false);
     }
 }

@@ -370,7 +354,7 @@ void Panel::setFloatingApplets(bool floatingApplets)
     if (panel()) {
         panel()->setFloatingApplets(floatingApplets);
     } else {
-        panelConfig().parent().writeEntry("floatingApplets", (int)floatingApplets);
+        panelConfigDefaults().parent().writeEntry("floatingApplets", (int)floatingApplets);
     }
 }

@@ -380,7 +364,7 @@ QString Panel::opacity() const
     if (panel()) {
         opacity = panel()->opacityMode();
     } else {
-        opacity = panelConfig().parent().readEntry("panelOpacity", 0);
+        opacity = panelConfigDefaults().parent().readEntry("panelOpacity", 0);
     }

     switch (opacity) {
@@ -410,7 +394,7 @@ void Panel::setOpacity(const QString &mode)
     if (panel()) {
         panel()->setOpacityMode(opacityMode);
     } else {
-        panelConfig().parent().writeEntry("panelOpacity", (int)opacityMode);
+        panelConfigDefaults().parent().writeEntry("panelOpacity", (int)opacityMode);
     }
 }
 }
diff --git a/shell/scripting/panel.h b/shell/scripting/panel.h
index 47b0c2b3b9..a92a63f897 100644
--- a/shell/scripting/panel.h
+++ b/shell/scripting/panel.h
@@ -98,7 +98,6 @@ public Q_SLOTS:

 private:
     PanelView *panel() const;
-    KConfigGroup panelConfig() const;
     KConfigGroup panelConfigDefaults() const;

     ShellCorona *m_corona;
-- 
